// 巡回するRSSフィード一覧（詳細: docs/workflow-design.md 2章）
// 新しいフィードを追加する場合はここに1行足すだけでよい
return [
  { json: { url: "https://news.yahoo.co.jp/rss/media/toyo/all.xml", source: "東洋経済オンライン(Yahoo)" } },
  { json: { url: "https://news.yahoo.co.jp/rss/media/president/all.xml", source: "プレジデントオンライン(Yahoo)" } },
  { json: { url: "https://news.yahoo.co.jp/rss/categories/business.xml", source: "Yahoo!ニュース ビジネス" } },
  { json: { url: "https://news.mynavi.jp/rss/kurashi/life/career.xml", source: "マイナビニュース キャリア" } },
  { json: { url: "https://news.mynavi.jp/rss/kurashi/jobhunting.xml", source: "マイナビニュース 転職" } },
  { json: { url: "https://jinjibu.jp/rss/?mode=news", source: "日本の人事部" } }
];

// RSS全フィード分の見出し(この時点で入力item)と、
// GSC検索パフォーマンス(別ブランチのノードを名前参照で取得)を整形し、
// Claudeへ渡す1件のテキストブロックにまとめる
const rssItems = $input.all();
const sorted = rssItems
  .map(i => i.json)
  .filter(j => j && j.title)
  .sort((a, b) => new Date(b.pubDate || b.isoDate || 0) - new Date(a.pubDate || a.isoDate || 0))
  .slice(0, 20);
const news_summary = sorted.length
  ? sorted.map(j => `- ${j.title}${j.pubDate ? `（${j.pubDate}）` : ''}`).join('\n')
  : 'ニュース見出しを取得できませんでした（RSS取得エラーの可能性）。';

let gsc_summary = 'GSC連携が未設定のため、今回は検索データなしで進める（automation/n8n/docs/google-search-console-setup.md Part B参照）。';
try {
  const gscJson = $('GSC検索パフォーマンス取得').first().json;
  if (gscJson && Array.isArray(gscJson.rows) && gscJson.rows.length > 0) {
    gsc_summary = gscJson.rows
      .slice(0, 15)
      .map(r => `- ${(r.keys && r.keys[0]) || '(不明なクエリ)'}: クリック${r.clicks}件 / 表示${r.impressions}回 / 平均掲載順位${(r.position || 0).toFixed(1)}`)
      .join('\n');
  }
} catch (e) {
  // GSC未連携・エラー時はニュースのみで進める
}

return [{ json: { gsc_summary, news_summary } }];

