// Claudeのレスポンス(content配列)からアイデアを取り出し、
// post_type/target_persona/source_summaryは共通のまま、4媒体分にファンアウトする。
// あわせて、Workflow03が生成した記事のアイキャッチ画像URLを受け取り、
// SNS投稿でもそのまま使い回せるようにする(ユーザー要望: 記事用画像をSNSにも使い回す)。
// 媒体ごとのおすすめ投稿時刻(JST)は、sns-viral-patterns.mdの知見に基づく簡易な目安。
//
// フラットなキー構成にしているのは、ネストしたオブジェクト(sns_idea/seo_idea)を
// tool_useのinput_schemaに使うと、Claudeがネスト構造を無視して1つの文字列に
// まとめて書いてしまう不具合が実際に発生したため(2026-07-03)。
//
// このノードの直接の上流(グラフ上の$input)はWorkflow03を実行(SEO記事1本)であり、
// Claudeでアイデア生成ではない(Workflow03を間に挟む順次実行のため)。
// そのためtool_use応答は$inputではなく名前参照で取得する。
const content = $('Claudeでアイデア生成').first().json.content ?? [];
const toolUse = content.find(b => b.type === 'tool_use' && b.name === 'submit_ideas');
if (!toolUse) {
  throw new Error('Claude応答にtool_useブロックが見つかりませんでした: ' + JSON.stringify(content).slice(0, 300));
}
const input = toolUse.input;

// Workflow03の実行結果からeyecatch_urlを取得する(失敗時・未実行時は空のまま進める)
let articleImageUrl = '';
try {
  const wf03Result = $('Workflow03を実行(SEO記事1本)').first().json;
  articleImageUrl = wf03Result?.article?.eyecatch_url || '';
} catch (e) {
  // Workflow03側が失敗していてもSNS側は続行する
}

// n8n CodeノードのJSサンドボックスは、コンテナのTZ環境変数(Asia/Tokyo)を継承せず
// UTC基準で動作する(実測で確認済み: setHours(8)がJST 8時ではなくUTC 8時になる)。
// そのためDate/getHours等のローカルタイムゾーン依存APIには頼らず、
// JST=UTC+9(夏時間なし・固定オフセット)であることを利用してUTC演算のみで計算する。
const JST_OFFSET_MS = 9 * 60 * 60 * 1000;
function nextDateAt(hourJST) {
  const nowJST = new Date(Date.now() + JST_OFFSET_MS);
  const y = nowJST.getUTCFullYear();
  const m = nowJST.getUTCMonth();
  const d = nowJST.getUTCDate();
  const tomorrowAtHourAsUTC = Date.UTC(y, m, d + 1, hourJST, 0, 0, 0);
  return new Date(tomorrowAtHourAsUTC - JST_OFFSET_MS).toISOString();
}

const PLATFORM_TIMES = {
  X: 8,
  Instagram: 12,
  Threads: 8,
  LINE: 12,
};

const platforms = ['X', 'Instagram', 'Threads', 'LINE'];
return platforms.map(platform => ({
  json: {
    platform,
    post_type: input.sns_post_type,
    target_persona: input.sns_target_persona,
    source_summary: input.sns_source_summary,
    article_image_url: articleImageUrl,
    suggested_post_datetime: nextDateAt(PLATFORM_TIMES[platform]),
  }
}));

// Claudeのtool_use出力(input)は既にパース済みオブジェクトなので、JSON.parseは不要
// フラットなキー構成にしているのは、ネストしたオブジェクト(sns_idea/seo_idea)を
// tool_useのinput_schemaに使うと、Claudeがネスト構造を無視して1つの文字列に
// まとめて書いてしまう不具合が実際に発生したため(2026-07-03)。
const content = $input.first().json.content ?? [];
const toolUse = content.find(b => b.type === 'tool_use' && b.name === 'submit_ideas');
if (!toolUse) {
  throw new Error('Claude応答にtool_useブロックが見つかりませんでした: ' + JSON.stringify(content).slice(0, 300));
}
const input = toolUse.input;
return [{
  json: {
    main_keyword: input.seo_main_keyword,
    target_reader: input.seo_target_reader,
    differentiation: input.seo_differentiation
  }
}];
